# Cross-language golden tests: the same fixture the Python package replays
# (regenerated by `cargo run --example golden`). Bit-exact on the platform
# that generated the fixture; across platforms libm ulp differences in the
# transcendentals require a tight relative tolerance.

test_that("R binding reproduces the golden fixture exactly", {
  skip_if_not_installed("jsonlite")
  gold <- jsonlite::read_json(test_path("golden.json"), simplifyVector = TRUE)

  ic <- ic_order(gold$series, "bic")
  expect_identical(ic$order, as.integer(gold$ic_bic$order))
  expect_equal(ic$values, gold$ic_bic$values, tolerance = 1e-9)

  fh <- fh_order(gold$series)
  expect_identical(fh$order, as.integer(gold$fh_pacf$order))
  expect_equal(fh$tau, gold$fh_pacf$tau, tolerance = 1e-9)
  expect_equal(fh$studentized, gold$fh_pacf$studentized, tolerance = 1e-9)

  svc <- svc_order(gold$series)
  expect_identical(svc$order, as.integer(gold$svc$order))
  expect_equal(svc$correlations, gold$svc$correlations, tolerance = 1e-9)

  hr <- hannan_rissanen(gold$series)
  expect_identical(c(hr$p, hr$q), as.integer(c(gold$hr$p, gold$hr$q)))
  expect_equal(hr$phi, gold$hr$phi, tolerance = 1e-9)
  expect_equal(hr$theta, gold$hr$theta, tolerance = 1e-9)

  expect_equal(qn(gold$short), gold$qn, tolerance = 1e-9)
  expect_equal(robust_acf(gold$series, 5), gold$robust_acf, tolerance = 1e-9)
  expect_identical(integration_order(gold$rw)$d, as.integer(gold$integration$d))
})
